import unittest
from candidate import same_chars

class TestSameChars(unittest.TestCase):
    def test_same_chars_normal_case(self):
        self.assertTrue(same_chars('eabcdzzzz', 'dddzzzzzzzddeddabc'))

    def test_same_chars_reversed(self):
        self.assertTrue(same_chars('abcd', 'dddddddabc'))

    def test_same_chars_partial_order(self):
        self.assertTrue(same_chars('dddddddabc', 'abcd'))

    def test_same_chars_mismatch(self):
        self.assertFalse(same_chars('eabcd', 'dddddddabc'))

    def test_same_chars_extra_char(self):
        self.assertFalse(same_chars('abcd', 'dddddddabce'))

    def test_same_chars_case_sensitive(self):
        self.assertFalse(same_chars('eabcdzzzz', 'dddZZZZZZZZDDDDabc'))

    def test_empty_strings(self):
        self.assertTrue(same_chars('', ''))

    def test_single_char_same(self):
        self.assertTrue(same_chars('a', 'a'))

    def test_single_char_different(self):
        self.assertFalse(same_chars('a', 'b'))

    def test_whitespace_ignored(self):
        self.assertTrue(same_chars('a b', 'a b'))

    def test_case_insensitivity(self):
        self.assertTrue(same_chars('AbCd', 'aBcD'))

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            same_chars(123, 'abc')

    def test_none_input(self):
        with self.assertRaises(TypeError):
            same_chars(None, 'abc')

    def test_mixed_types(self):
        with self.assertRaises(TypeError):
            same_chars('abc', 123)

    def test_long_strings(self):
        long_str1 = 'a' * 1000 + 'b' * 1000 + 'c' * 1000
        long_str2 = 'c' * 1000 + 'b' * 1000 + 'a' * 1000
        self.assertTrue(same_chars(long_str1, long_str2))

    def test_unicode_characters(self):
        self.assertTrue(same_chars('café', 'éfac'))
        self.assertFalse(same_chars('café', 'éfacd'))

    def test_duplicate_chars(self):
        self.assertTrue(same_chars('aabbcc', 'abcabc'))
        self.assertFalse(same_chars('aabbcc', 'aabbccd'))

if __name__ == '__main__':
    unittest.main()
